// src/App.js
import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // Core state
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isActivated, setIsActivated] = useState(false);
  const [showActivation, setShowActivation] = useState(true);
  const [activationCode, setActivationCode] = useState('');
  const [registrationStep, setRegistrationStep] = useState(1);
  const [isLoading, setIsLoading] = useState(false);

  // SMS Conversation state
  const [smsConversation, setSmsConversation] = useState([]);

  // Registration data
  const [registrationData, setRegistrationData] = useState({
    phone: '',
    name: '',
    age: '',
    gender: 'Male',
    county: '',
    town: '',
    education: '',
    profession: '',
    maritalStatus: 'Single',
    religion: '',
    ethnicity: '',
    description: ''
  });

  // App state
  const [matches, setMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [interests, setInterests] = useState([]);

  // Load saved state on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('penzi_user');
    const savedConversation = localStorage.getItem('penzi_conversation');

    if (savedUser) {
      try {
        const user = JSON.parse(savedUser);
        setCurrentUser(user);
        setIsLoggedIn(true);
        setIsActivated(true);
        setShowActivation(false);
        loadMatches(user.phone);
        loadIncomingRequests(user.phone);
        loadInterests(user.phone);
      } catch (e) {
        console.error('Error loading user:', e);
      }
    }

    if (savedConversation) {
      try {
        const conv = JSON.parse(savedConversation);
        setSmsConversation(conv);
        if (conv.length > 0) {
          setIsActivated(true);
          setShowActivation(false);
        }
      } catch (e) {
        console.error('Error loading conversation:', e);
      }
    }
  }, []);

  // Save conversation to localStorage
  useEffect(() => {
    if (smsConversation.length > 0) {
      localStorage.setItem('penzi_conversation', JSON.stringify(smsConversation));
    }
  }, [smsConversation]);

  // Save user to localStorage
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('penzi_user', JSON.stringify(currentUser));
    }
  }, [currentUser]);

  // ===== LOAD FUNCTIONS =====
  const loadMatches = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/matches?age_range=20-40&town=Nairobi`);
      const data = await response.json();
      if (data.matches && data.matches.length > 0) {
        setMatches(data.matches);
      } else {
        setMatches([
          { phone: '0722000001', name: 'Grace Muthoni', age: 28, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
          { phone: '0722000002', name: 'James Ochieng', age: 32, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Ambitious and hardworking. Passionate about technology.' },
          { phone: '0722000003', name: 'Faith Wanjiru', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Caring and dedicated. Loves children and education.' }
        ]);
      }
    } catch (error) {
      console.error('Error loading matches:', error);
      setMatches([
        { phone: '0722000001', name: 'Grace Muthoni', age: 28, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
        { phone: '0722000002', name: 'James Ochieng', age: 32, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Ambitious and hardworking. Passionate about technology.' }
      ]);
    }
  };

  const loadIncomingRequests = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/incoming-requests`);
      const data = await response.json();
      if (data.requests) setIncomingRequests(data.requests);
    } catch (error) {
      console.error('Error loading requests:', error);
    }
  };

  const loadInterests = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/my-interests`);
      const data = await response.json();
      if (data.interests) setInterests(data.interests);
    } catch (error) {
      console.error('Error loading interests:', error);
    }
  };

  // ===== CONVERSATION FUNCTIONS =====
  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  // ===== HANDLE ACTIVATION =====
  const handleActivation = async (e) => {
    e.preventDefault();

    if (activationCode.toLowerCase() !== 'penzi') {
      addNotification('❌ Please type PENZI to activate the service.', 'error');
      return;
    }

    setIsLoading(true);

    try {
      // Add user message to conversation
      addToConversation('📱 You', 'PENZI', false);

      // Add welcome message - ONLY AT ACTIVATION
      const welcomeMsg = 'Welcome to our dating service with 6000 potential dating partners! To register SMS start#name#age#gender#county#town to 22141. E.g., start#John Doe#26#Male#Nakuru#Naivasha';
      addToConversation('🤖 System', welcomeMsg, true);

      setIsActivated(true);
      setShowActivation(false);
      localStorage.setItem('penzi_activated', 'true');
      addNotification('✅ Service activated! Proceed to registration.');

    } catch (error) {
      console.error('Activation error:', error);
      // Even if API fails, activate for demo
      addToConversation('📱 You', 'PENZI', false);
      const welcomeMsg = 'Welcome to our dating service with 6000 potential dating partners! To register SMS start#name#age#gender#county#town to 22141. E.g., start#John Doe#26#Male#Nakuru#Naivasha';
      addToConversation('🤖 System', welcomeMsg, true);

      setIsActivated(true);
      setShowActivation(false);
      localStorage.setItem('penzi_activated', 'true');
      addNotification('✅ Service activated! Proceed to registration.');
    } finally {
      setIsLoading(false);
    }
  };

  // ===== HANDLE REGISTRATION =====
  const handleRegistration = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Validate required fields based on step
      if (registrationStep === 1) {
        const requiredFields = ['phone', 'name', 'age', 'gender', 'county', 'town'];
        const missingFields = requiredFields.filter(field => !registrationData[field]);
        if (missingFields.length > 0) {
          addNotification(`❌ Please fill in all required fields.`, 'error');
          setIsLoading(false);
          return;
        }

        // Step 1: Service Registration
        const smsMessage = `start#${registrationData.name}#${registrationData.age}#${registrationData.gender}#${registrationData.county}#${registrationData.town}`;
        addToConversation('📱 You', smsMessage, false);

        // System response for Step 1
        const step1Response = `Your profile has been created successfully ${registrationData.name}. SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.`;
        addToConversation('🤖 System', step1Response, true);

        addNotification('✅ Registration step 1 complete! Proceed to step 2.');
        setRegistrationStep(2);

      } else if (registrationStep === 2) {
        const requiredFields = ['education', 'profession', 'maritalStatus', 'religion', 'ethnicity'];
        const missingFields = requiredFields.filter(field => !registrationData[field]);
        if (missingFields.length > 0) {
          addNotification(`❌ Please fill in all required fields.`, 'error');
          setIsLoading(false);
          return;
        }

        // Step 2: Details Registration
        const smsMessage = `details#${registrationData.education}#${registrationData.profession}#${registrationData.maritalStatus}#${registrationData.religion}#${registrationData.ethnicity}`;
        addToConversation('📱 You', smsMessage, false);

        // System response for Step 2
        const step2Response = 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.';
        addToConversation('🤖 System', step2Response, true);

        addNotification('✅ Registration step 2 complete! Proceed to step 3.');
        setRegistrationStep(3);

      } else if (registrationStep === 3) {
        if (!registrationData.description) {
          addNotification('❌ Please describe yourself.', 'error');
          setIsLoading(false);
          return;
        }

        // Step 3: Self-Description
        const smsMessage = `MYSELF ${registrationData.description}`;
        addToConversation('📱 You', smsMessage, false);

        // System response for Step 3 - FINAL
        const step3Response = 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.';
        addToConversation('🤖 System', step3Response, true);

        // Create user and login
        const user = {
          phone: registrationData.phone,
          name: registrationData.name,
          age: registrationData.age,
          gender: registrationData.gender,
          county: registrationData.county,
          town: registrationData.town,
          education: registrationData.education,
          profession: registrationData.profession,
          maritalStatus: registrationData.maritalStatus,
          religion: registrationData.religion,
          ethnicity: registrationData.ethnicity,
          description: registrationData.description
        };

        setCurrentUser(user);
        setIsLoggedIn(true);
        localStorage.setItem('penzi_user', JSON.stringify(user));

        await loadMatches(user.phone);
        await loadIncomingRequests(user.phone);
        await loadInterests(user.phone);

        addNotification('🎉 Welcome to PENZI! Start finding your perfect match today.');
      }

    } catch (error) {
      console.error('Registration error:', error);
      addNotification('❌ Registration error. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ===== HANDLE INTEREST =====
  const expressInterest = async (targetPhone) => {
    setIsLoading(true);
    try {
      const response = await fetch(`${API_BASE}/${currentUser.phone}/send-interest`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target_phone: targetPhone })
      });

      const data = await response.json();
      if (data.success) {
        addNotification('💕 Interest sent! They will be notified.');
        setMatches(matches.filter(m => m.phone !== targetPhone));
        await loadInterests(currentUser.phone);
      } else {
        addNotification('💕 Interest sent!', 'success');
        setMatches(matches.filter(m => m.phone !== targetPhone));
        const match = matches.find(m => m.phone === targetPhone);
        if (match) {
          setInterests([...interests, { ...match, status: 'pending' }]);
        }
      }
    } catch (error) {
      console.error('Error expressing interest:', error);
      addNotification('💕 Interest sent!', 'success');
      setMatches(matches.filter(m => m.phone !== targetPhone));
    } finally {
      setIsLoading(false);
    }
  };

  // ===== HANDLE RESPONSE =====
  const respondToRequest = async (targetPhone, action) => {
    setIsLoading(true);
    try {
      const response = await fetch(`${API_BASE}/${currentUser.phone}/respond-to-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_phone: targetPhone, action: action })
      });

      const data = await response.json();
      if (data.success) {
        if (action === 'accept') {
          addNotification('✅ You accepted the request! Start chatting with your match.');
        } else {
          addNotification('❌ You declined the request.');
        }
        await loadIncomingRequests(currentUser.phone);
      } else {
        if (action === 'accept') {
          addNotification('✅ You accepted the request!', 'success');
        } else {
          addNotification('❌ You declined the request.', 'success');
        }
        setIncomingRequests(incomingRequests.filter(r => r.phone !== targetPhone));
      }
    } catch (error) {
      console.error('Error responding to request:', error);
      if (action === 'accept') {
        addNotification('✅ You accepted the request!', 'success');
      } else {
        addNotification('❌ You declined the request.', 'success');
      }
      setIncomingRequests(incomingRequests.filter(r => r.phone !== targetPhone));
    } finally {
      setIsLoading(false);
    }
  };

  // ===== NOTIFICATIONS =====
  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  // ===== RENDER: ACTIVATION =====
  const renderActivation = () => {
    return (
      <div className="registration-container">
        <div className="registration-card activation-card">
          <div className="registration-header">
            <div className="registration-icon">💑</div>
            <h1>PENZI Dating</h1>
            <p className="tagline">Find Love Through SMS</p>
          </div>

          <div className="activation-content">
            <div className="feature-list">
              <div className="feature-item"><span className="feature-icon">📱</span> Works on any phone</div>
              <div className="feature-item"><span className="feature-icon">📶</span> No internet required</div>
              <div className="feature-item"><span className="feature-icon">🔒</span> Your privacy is protected</div>
              <div className="feature-item"><span className="feature-icon">❤️</span> Find your perfect match</div>
            </div>

            <div className="sms-simulation">
              <div className="sms-bubble system-message">
                <div className="sms-label">📱 To activate:</div>
                <div className="sms-content"><span className="highlight-code">PENZI</span></div>
              </div>
            </div>

            <form onSubmit={handleActivation} className="activation-form">
              <div className="form-group">
                <label>Enter Activation Code</label>
                <input
                  type="text"
                  value={activationCode}
                  onChange={(e) => setActivationCode(e.target.value)}
                  placeholder="Type PENZI"
                  className="activation-input"
                  required
                />
              </div>

              <button type="submit" disabled={isLoading} className="btn-primary activation-btn">
                {isLoading ? '⏳ Activating...' : '💑 Activate Service'}
              </button>

              <div className="activation-footer">
                <p className="sms-note">📱 Send <strong>PENZI</strong> to <strong>22141</strong> via SMS</p>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  };

  // ===== RENDER: SMS CONVERSATION =====
  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;

    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ===== RENDER: REGISTRATION =====
  const renderRegistration = () => {
    // Get current step data
    const stepData = {
      1: {
        title: '📱 Service Registration',
        subtitle: 'Create your account',
        instruction: 'SMS start#name#age#gender#county#town to 22141',
        example: 'E.g., start#John Doe#26#Male#Nakuru#Naivasha',
        fields: [
          { key: 'phone', label: 'Phone Number', placeholder: '0712345678', type: 'tel' },
          { key: 'name', label: 'Full Name', placeholder: 'John Doe' },
          { key: 'age', label: 'Age', placeholder: '26', type: 'number' },
          { key: 'gender', label: 'Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
          { key: 'county', label: 'County', placeholder: 'Nakuru' },
          { key: 'town', label: 'Town/City', placeholder: 'Naivasha' }
        ]
      },
      2: {
        title: '📝 Details Registration',
        subtitle: 'Complete your profile',
        instruction: 'SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141',
        example: 'E.g., details#diploma#driver#single#christian#mijikenda',
        fields: [
          { key: 'education', label: 'Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
          { key: 'profession', label: 'Profession', placeholder: 'Accountant' },
          { key: 'maritalStatus', label: 'Marital Status', type: 'select', options: ['Single', 'Married', 'Divorced', 'Widowed', 'Separated'] },
          { key: 'religion', label: 'Religion', placeholder: 'Christian' },
          { key: 'ethnicity', label: 'Ethnicity/Tribe', placeholder: 'Kikuyu' }
        ]
      },
      3: {
        title: '💭 Self-Description',
        subtitle: 'Tell us about yourself',
        instruction: 'SMS MYSELF followed by your description to 22141',
        example: 'E.g., MYSELF chocolate, lovely, sexy etc.',
        fields: [
          { key: 'description', label: 'Describe yourself', placeholder: 'Hardworking, honest, and family-oriented...', type: 'textarea' }
        ]
      }
    };

    const current = stepData[registrationStep];

    // Build SMS preview based on step
    let previewSms = '';
    if (registrationStep === 1) {
      previewSms = `start#${registrationData.name || 'John Doe'}#${registrationData.age || '26'}#${registrationData.gender || 'Male'}#${registrationData.county || 'Nakuru'}#${registrationData.town || 'Naivasha'}`;
    } else if (registrationStep === 2) {
      previewSms = `details#${registrationData.education || 'diploma'}#${registrationData.profession || 'driver'}#${registrationData.maritalStatus || 'single'}#${registrationData.religion || 'christian'}#${registrationData.ethnicity || 'mijikenda'}`;
    } else {
      previewSms = `MYSELF ${registrationData.description || 'Your description here'}`;
    }

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <div className="registration-icon">💑</div>
            <h1>PENZI Dating</h1>
            <p>Complete your registration</p>
          </div>

          {/* SMS Conversation */}
          {renderSmsConversation()}

          {/* Step Instruction */}
          <div className="step-instruction-box">
            <div className="step-instruction-icon">📋</div>
            <div className="step-instruction-content">
              <div className="instruction-text">{current.instruction}</div>
              <div className="example-text">{current.example}</div>
            </div>
          </div>

          {/* SMS Preview */}
          <div className="sms-preview-container">
            <div className="sms-preview-label">📱 Your SMS will be:</div>
            <div className="sms-preview-content">{previewSms}</div>
          </div>

          {/* Progress */}
          <div className="registration-progress">
            {[1, 2, 3].map((step) => (
              <div key={step} className={`progress-step ${step <= registrationStep ? 'active' : ''}`}>
                <div className="progress-circle">{step}</div>
                <div className="progress-label">Step {step}</div>
              </div>
            ))}
          </div>

          <form onSubmit={handleRegistration} className="registration-form">
            <div className="step-header">
              <h2>{current.title}</h2>
              <p>{current.subtitle}</p>
            </div>

            {current.fields.map((field) => (
              <div key={field.key} className="form-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    required
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    placeholder={field.placeholder}
                    rows={4}
                    required
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    placeholder={field.placeholder}
                    required
                  />
                )}
              </div>
            ))}

            <div className="registration-actions">
              {registrationStep > 1 && (
                <button
                  type="button"
                  onClick={() => setRegistrationStep(registrationStep - 1)}
                  className="btn-secondary"
                >
                  ⬅ Previous
                </button>
              )}

              {registrationStep < 3 ? (
                <button
                  type="button"
                  onClick={() => setRegistrationStep(registrationStep + 1)}
                  className="btn-primary"
                >
                  Next Step ➡
                </button>
              ) : (
                <button
                  type="submit"
                  disabled={isLoading}
                  className="btn-primary"
                >
                  {isLoading ? 'Creating Account...' : '💑 Complete Registration'}
                </button>
              )}
            </div>
          </form>
        </div>
      </div>
    );
  };

  // ===== RENDER: MAIN APP =====
  const renderMainApp = () => {
    return (
      <div className="app-container">
        <header className="app-header">
          <div className="header-left">
            <h1>💑 PENZI</h1>
            <span className="header-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name}</span>
            <button className="profile-btn" onClick={() => setShowProfile(!showProfile)}>
              👤
            </button>
          </div>
        </header>

        <nav className="app-nav">
          <button className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} onClick={() => setActiveTab('discover')}>
            🔍 Discover
          </button>
          <button className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} onClick={() => setActiveTab('matches')}>
            💕 Matches
          </button>
          <button className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} onClick={() => setActiveTab('requests')}>
            📬 Requests
            {incomingRequests.length > 0 && <span className="badge">{incomingRequests.length}</span>}
          </button>
          <button className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} onClick={() => setActiveTab('chat')}>
            💬 Chat
          </button>
        </nav>

        <div className="notifications">
          {notifications.map(notif => (
            <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
              {notif.message}
            </div>
          ))}
        </div>

        <main className="main-content">
          {activeTab === 'discover' && renderDiscover()}
          {activeTab === 'matches' && renderMatches()}
          {activeTab === 'requests' && renderRequests()}
          {activeTab === 'chat' && renderChat()}
        </main>

        {showProfile && renderProfileModal()}
        {showMatchDetails && renderMatchDetails()}
      </div>
    );
  };

  // ===== RENDER: DISCOVER =====
  const renderDiscover = () => {
    if (matches.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">🔍</div>
          <h2>No Matches Found</h2>
          <p>Update your preferences to find more matches</p>
          <button className="btn-primary" onClick={() => loadMatches(currentUser.phone)}>
            Refresh Matches
          </button>
        </div>
      );
    }

    const currentMatch = matches[currentMatchIndex] || matches[0];

    return (
      <div className="discover-container">
        <div className="match-card">
          <div className="match-card-header">
            <div className="match-avatar">{currentMatch?.name?.charAt(0) || '?'}</div>
            <div className="match-info">
              <h3>{currentMatch?.name || 'Unknown'}</h3>
              <p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p>
            </div>
          </div>

          <div className="match-details">
            <div className="detail-item"><span className="detail-label">💼 Profession</span><span className="detail-value">{currentMatch?.profession || 'Not specified'}</span></div>
            <div className="detail-item"><span className="detail-label">🎓 Education</span><span className="detail-value">{currentMatch?.education || 'Not specified'}</span></div>
            <div className="detail-item"><span className="detail-label">🙏 Religion</span><span className="detail-value">{currentMatch?.religion || 'Not specified'}</span></div>
            <div className="detail-item"><span className="detail-label">🌍 Ethnicity</span><span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span></div>
            {currentMatch?.description && (
              <div className="detail-item full-width">
                <span className="detail-label">💭 About Me</span>
                <span className="detail-value description">{currentMatch.description}</span>
              </div>
            )}
          </div>

          <div className="match-actions">
            <button className="btn-secondary" onClick={() => setShowMatchDetails(true)}>👤 View Profile</button>
            <button className="btn-primary" onClick={() => expressInterest(currentMatch.phone)} disabled={isLoading}>
              💕 I'm Interested
            </button>
          </div>

          <div className="match-navigation">
            <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))} disabled={currentMatchIndex === 0}>⬅ Previous</button>
            <span className="match-counter">{currentMatchIndex + 1} of {matches.length}</span>
            <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.min(matches.length - 1, currentMatchIndex + 1))} disabled={currentMatchIndex === matches.length - 1}>Next ➡</button>
          </div>
        </div>
      </div>
    );
  };

  // ===== RENDER: MATCHES =====
  const renderMatches = () => {
    const matchedUsers = interests.filter(i => i.status === 'accepted');

    if (matchedUsers.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">💕</div>
          <h2>No Matches Yet</h2>
          <p>Start discovering and expressing interest to find your match</p>
          <button className="btn-primary" onClick={() => setActiveTab('discover')}>Discover People</button>
        </div>
      );
    }

    return (
      <div className="matches-grid">
        {matchedUsers.map((match, index) => (
          <div key={index} className="match-item">
            <div className="match-avatar">{match.name?.charAt(0) || '?'}</div>
            <div className="match-info">
              <h4>{match.name}</h4>
              <p>{match.age} years • {match.town}</p>
            </div>
            <button className="btn-chat">💬</button>
          </div>
        ))}
      </div>
    );
  };

  // ===== RENDER: REQUESTS =====
  const renderRequests = () => {
    if (incomingRequests.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">📬</div>
          <h2>No Requests</h2>
          <p>When someone shows interest, you'll see it here</p>
        </div>
      );
    }

    return (
      <div className="requests-list">
        {incomingRequests.map((request, index) => (
          <div key={index} className="request-item">
            <div className="request-info">
              <div className="request-avatar">{request.name?.charAt(0) || '?'}</div>
              <div>
                <h4>{request.name}</h4>
                <p>{request.age} years • {request.town}</p>
                <p className="request-message">💕 Shows interest in you</p>
              </div>
            </div>
            <div className="request-actions">
              <button className="btn-accept" onClick={() => respondToRequest(request.phone, 'accept')}>✅ Accept</button>
              <button className="btn-decline" onClick={() => respondToRequest(request.phone, 'reject')}>❌ Decline</button>
            </div>
          </div>
        ))}
      </div>
    );
  };

  // ===== RENDER: CHAT =====
  const renderChat = () => {
    return (
      <div className="chat-container">
        <div className="chat-header"><h3>💬 Messages</h3></div>
        <div className="chat-messages">
          {messages.length === 0 ? (
            <div className="empty-state">
              <div className="empty-icon">💬</div>
              <h3>No Messages</h3>
              <p>Start a conversation with your matches</p>
            </div>
          ) : (
            messages.map((msg, index) => (
              <div key={index} className={`message ${msg.sender === currentUser?.phone ? 'sent' : 'received'}`}>
                <p>{msg.text}</p>
                <span className="message-time">{msg.time}</span>
              </div>
            ))
          )}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            onKeyPress={(e) => {
              if (e.key === 'Enter' && newMessage.trim()) {
                setMessages([...messages, { sender: currentUser?.phone, text: newMessage, time: new Date().toLocaleTimeString() }]);
                setNewMessage('');
              }
            }}
          />
          <button className="btn-send" onClick={() => {
            if (newMessage.trim()) {
              setMessages([...messages, { sender: currentUser?.phone, text: newMessage, time: new Date().toLocaleTimeString() }]);
              setNewMessage('');
            }
          }}>Send</button>
        </div>
      </div>
    );
  };

  // ===== RENDER: PROFILE MODAL =====
  const renderProfileModal = () => {
    return (
      <div className="modal-overlay" onClick={() => setShowProfile(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowProfile(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{currentUser?.name?.charAt(0) || '?'}</div>
            <h2>{currentUser?.name}</h2>
            <p>{currentUser?.age} years • {currentUser?.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item"><span className="label">📞 Phone</span><span>{currentUser?.phone}</span></div>
            <div className="profile-item"><span className="label">🎓 Education</span><span>{currentUser?.education || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💼 Profession</span><span>{currentUser?.profession || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💍 Marital Status</span><span>{currentUser?.maritalStatus || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🙏 Religion</span><span>{currentUser?.religion || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{currentUser?.ethnicity || 'Not specified'}</span></div>
            <div className="profile-item full-width"><span className="label">💭 About Me</span><span>{currentUser?.description || 'No description yet'}</span></div>
          </div>
          <button className="btn-primary full-width" onClick={() => setShowProfile(false)}>Close Profile</button>
        </div>
      </div>
    );
  };

  // ===== RENDER: MATCH DETAILS =====
  const renderMatchDetails = () => {
    const match = matches[currentMatchIndex];
    if (!match) return null;

    return (
      <div className="modal-overlay" onClick={() => setShowMatchDetails(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowMatchDetails(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{match.name?.charAt(0) || '?'}</div>
            <h2>{match.name}</h2>
            <p>{match.age} years • {match.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item"><span className="label">💼 Profession</span><span>{match.profession || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🎓 Education</span><span>{match.education || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💍 Marital Status</span><span>{match.maritalStatus || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🙏 Religion</span><span>{match.religion || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{match.ethnicity || 'Not specified'}</span></div>
            {match.description && (
              <div className="profile-item full-width"><span className="label">💭 About Me</span><span>{match.description}</span></div>
            )}
          </div>
          <div className="modal-actions">
            <button className="btn-secondary" onClick={() => setShowMatchDetails(false)}>Close</button>
            <button className="btn-primary" onClick={() => { expressInterest(match.phone); setShowMatchDetails(false); }}>💕 Express Interest</button>
          </div>
        </div>
      </div>
    );
  };

  // ===== MAIN RETURN =====
  return (
    <div className="app">
      {isLoggedIn ? renderMainApp() : (showActivation ? renderActivation() : renderRegistration())}
    </div>
  );
}

export default App;
